use serde::{Deserialize, Serialize};
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)] pub enum TunnelType { Local, Remote, Dynamic }
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)] pub struct TunnelConfig { pub tunnel_type: TunnelType, pub host_alias: String, pub bind_address: Option<String>, pub local_port: u16, pub target_host: Option<String>, pub target_port: Option<u16> }
impl TunnelConfig { pub fn command(&self) -> String { match self.tunnel_type { TunnelType::Local => format!("ssh -L {}{}:{}:{} {}", bind(&self.bind_address), self.local_port, self.target_host.clone().unwrap_or_else(||"localhost".into()), self.target_port.unwrap_or(80), shell_words::quote(&self.host_alias)), TunnelType::Remote => format!("ssh -R {}{}:{}:{} {}", bind(&self.bind_address), self.local_port, self.target_host.clone().unwrap_or_else(||"localhost".into()), self.target_port.unwrap_or(80), shell_words::quote(&self.host_alias)), TunnelType::Dynamic => format!("ssh -D {}{} {}", bind(&self.bind_address), self.local_port, shell_words::quote(&self.host_alias)), } } }
fn bind(b:&Option<String>)->String{ b.as_ref().map(|s| format!("{}:",s)).unwrap_or_default() }
#[cfg(test)] mod tests { use super::*; #[test] fn local_tunnel_command(){ let t=TunnelConfig{tunnel_type:TunnelType::Local,host_alias:"web-prod-1".into(),bind_address:None,local_port:8080,target_host:Some("localhost".into()),target_port:Some(80)}; assert_eq!(t.command(),"ssh -L 8080:localhost:80 web-prod-1"); } #[test] fn dynamic_tunnel_command(){ let t=TunnelConfig{tunnel_type:TunnelType::Dynamic,host_alias:"web prod".into(),bind_address:Some("127.0.0.1".into()),local_port:1080,target_host:None,target_port:None}; assert_eq!(t.command(),"ssh -D 127.0.0.1:1080 'web prod'"); } }
